import{_ as p,a0 as o,w as d,s as r,I as t,x as e,a1 as a,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用 K3s 在樹莓派上運行 Kubernetes 集羣 | LCTT x X-CMD","titleTemplate":false,"description":"使用 K3s 在樹莓派上運行 Kubernetes 集羣 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 K3s 在樹莓派上運行 Kubernetes 集羣 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 K3s 在樹莓派上運行 Kubernetes 集羣 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200310 Run Kubernetes on a Raspberry Pi with k3s","title":"使用 K3s 在樹莓派上運行 Kubernetes 集羣","tag":"202003","desc":""},"relativePath":"202003/20200310 Run Kubernetes on a Raspberry Pi with k3s.md","filePath":"[post].md"}'),k={name:"202003/20200310 Run Kubernetes on a Raspberry Pi with k3s.md"};function u(h,s,b,g,c,f){const i=o("Link");return d(),r("div",null,[s[41]||(s[41]=t("h1",{id:"使用-k3s-在樹莓派上運行-kubernetes-集羣",tabindex:"-1"},[e("使用 K3s 在樹莓派上運行 Kubernetes 集羣 "),t("a",{class:"header-anchor",href:"#使用-k3s-在樹莓派上運行-kubernetes-集羣","aria-label":"Permalink to “使用 K3s 在樹莓派上運行 Kubernetes 集羣”"},"​")],-1)),s[42]||(s[42]=t("blockquote",null,[t("p",null,"跟隨接下來的介紹，自己搭建一個三節點的 Kubernetes 集羣。")],-1)),s[43]||(s[43]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202003/29/121559p44e3dfrerf3zver.jpg",alt:""})],-1)),t("p",null,[s[1]||(s[1]=e("我對在樹莓派上搭建 ",-1)),a(i,{href:"https://opensource.com/resources/what-is-kubernetes"},{default:n(()=>[...s[0]||(s[0]=[e("Kubernetes",-1)])]),_:1}),s[2]||(s[2]=e(" 集羣已經感興趣很長時間了，只要照着網上的教程，我可以在由三個樹莓派組成的集羣中搭建一套 Kubernetes 並正常運行。但在這種情況下，主節點上的內存和 CPU 資源捉襟見肘，執行 Kubernetes 任務的時候往往性能不佳，想要升級 Kubernetes 就更不可能了。",-1))]),t("p",null,[s[4]||(s[4]=e("這個時候，我非常激動地發現了 ",-1)),a(i,{href:"https://k3s.io/"},{default:n(()=>[...s[3]||(s[3]=[e("K3s",-1)])]),_:1}),s[5]||(s[5]=e(" 這個項目。K3s 被譽為在可用於資源受限環境下的輕量級 Kubernetes，它還針對 ARM 處理器做出了優化，這讓 Kubernetes 集羣可以在樹莓派上運行得更好。在下文中，我們將會使用 K3s 來創建一個 Kubernetes 集羣。",-1))]),t("ul",null,[t("li",null,[a(i,{href:"https://youtu.be/6PqxJhV-t1s"},{default:n(()=>[...s[6]||(s[6]=[e("video",-1)])]),_:1})])]),s[44]||(s[44]=l(`<h3 id="準備" tabindex="-1">準備 <a class="header-anchor" href="#準備" aria-label="Permalink to “準備”">​</a></h3><p>要按照本文介紹的方式創建 Kubernetes 集羣，首先需要準備：</p><ul><li>至少一個樹莓派（包括 SD 卡和電源）</li><li>網線</li><li>將所有樹莓派連接到一起的交換機或路由器</li></ul><p>我們會通過在線安裝的方式安裝 K3s，因此還需要可以連接到互聯網。</p><h3 id="集羣概覽" tabindex="-1">集羣概覽 <a class="header-anchor" href="#集羣概覽" aria-label="Permalink to “集羣概覽”">​</a></h3><p>在這個集羣裏，我們會使用三個樹莓派。其中一個樹莓派作為主節點，我們將它命名為 <code>kmaster</code>，併為其分配一個靜態 IP <code>192.168.0.50</code>（注：假設使用的私有網段是 192.168.0.0/24），而另外兩個樹莓派作為工作節點，分別命名為 <code>knode1</code> 和 <code>knode2</code>，也分別分配 <code>192.168.0.51</code> 和 <code>192.168.0.52</code> 兩個 IP 地址。</p><p>當然，如果你實際的網絡佈局和上面不同，只要將文中所提及到的 IP 替換成你實際可用的 IP 就可以了。</p><p>為了不需要通過 IP 來引用某一個節點，我們將每個節點的主機名記錄到 PC 的 <code>/etc/hosts</code> 文件當中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo -e &quot;192.168.0.50\\tkmaster&quot; | sudo tee -a /etc/hosts</span></span>
<span class="line"><span>echo -e &quot;192.168.0.51\\tknode1&quot; | sudo tee -a /etc/hosts</span></span>
<span class="line"><span>echo -e &quot;192.168.0.52\\tknode2&quot; | sudo tee -a /etc/hosts</span></span></code></pre></div><h3 id="部署主節點" tabindex="-1">部署主節點 <a class="header-anchor" href="#部署主節點" aria-label="Permalink to “部署主節點”">​</a></h3>`,10)),t("p",null,[s[8]||(s[8]=e("我們首先部署主節點。最開始的步驟當然是使用鏡像安裝最新的 Raspbian，這個步驟可以參考我的",-1)),a(i,{href:"https://carpie.net/articles/headless-pi-with-static-ip-wired-edition"},{default:n(()=>[...s[7]||(s[7]=[e("另一篇文章",-1)])]),_:1}),s[9]||(s[9]=e("，在這裏就不展開介紹了。在安裝完成之後，啓動 SSH 服務，將主機名設置為 ",-1)),s[10]||(s[10]=t("code",null,"kmaster",-1)),s[11]||(s[11]=e("，然後分配靜態 IP ",-1)),s[12]||(s[12]=t("code",null,"192.168.0.50",-1)),s[13]||(s[13]=e("。",-1))]),s[45]||(s[45]=l(`<p>在主節點上安裝 Raspbian 完成後，啓動樹莓派並通過 <code>ssh</code> 連接上去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh pi@kmaster</span></span></code></pre></div><p>在主節點上執行以下命令安裝 K3s：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curl -sfL https://get.k3s.io | sh -</span></span></code></pre></div><p>等到命令跑完以後，一個單節點集羣就已經運行起來了。讓我們檢查一下，還在這個樹莓派上執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo kubectl get nodes</span></span></code></pre></div><p>就會看到這樣的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME     STATUS   ROLES    AGE    VERSION</span></span>
<span class="line"><span>kmaster  Ready    master   2m13s  v1.14.3-k3s.1</span></span></code></pre></div><h3 id="獲取連接令牌join-token" tabindex="-1">獲取<ruby>連接令牌<rt>join token</rt></ruby> <a class="header-anchor" href="#獲取連接令牌join-token" aria-label="Permalink to “獲取連接令牌join token”">​</a></h3><p>之後我們需要部署工作節點。在工作節點上安裝 K3s 的時候，會需要用到連接令牌，它放置在主節點的文件系統上。首先把連接令牌保存出來以便後續使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cat /var/lib/rancher/k3s/server/node-token</span></span></code></pre></div><h3 id="部署工作節點" tabindex="-1">部署工作節點 <a class="header-anchor" href="#部署工作節點" aria-label="Permalink to “部署工作節點”">​</a></h3><p>通過 SD 卡在每個作為工作節點的樹莓派上安裝 Raspbian。在這裏，我們把其中一個樹莓派的主機名設置為 <code>knode1</code>，為其分配 IP 地址 <code>192.168.0.51</code>，另一個樹莓派的主機名設置為 <code>knode2</code>，分配 IP 地址 <code>192.168.0.52</code>。接下來就可以安裝 K3s 了。</p><p>啓動主機名為 <code>knode1</code> 的樹莓派，通過 <code>ssh</code> 連接上去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh pi@knode1</span></span></code></pre></div><p>在這個樹莓派上，安裝 K3s 的過程和之前差不多，但需要另外加上一些參數，表示它是一個工作節點，需要連接到一個已有的集羣上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curl -sfL http://get.k3s.io | K3S_URL=https://192.168.0.50:6443 \\</span></span>
<span class="line"><span>K3S_TOKEN=剛才保存下來的連接令牌 sh -</span></span></code></pre></div><p><code>K3S_TOKEN</code> 的值需要替換成剛才保存下來的實際的連接令牌。完成之後，在主機名為 <code>knode2</code> 的樹莓派上重複這個安裝過程。</p><h3 id="通過-pc-訪問集羣" tabindex="-1">通過 PC 訪問集羣 <a class="header-anchor" href="#通過-pc-訪問集羣" aria-label="Permalink to “通過 PC 訪問集羣”">​</a></h3><p>現在如果我們想要查看或者更改集羣，都必須 <code>ssh</code> 到集羣的主節點才能使用 <code>kubectl</code>，這是比較麻煩的。因此我們會將 <code>kubectl</code> 放到 PC 上使用。首先，在主節點上獲取一些必要的配置信息，<code>ssh</code> 到 <code>kmaster</code> 上執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cat /etc/rancher/k3s/k3s.yaml</span></span></code></pre></div><p>複製上面命令的輸出，然後在你的 PC 上創建一個目錄用來放置配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir ~/.kube</span></span></code></pre></div><p>將複製好的內容寫入到 <code>~/.kube/config</code> 文件中，然後編輯該文件，將</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server: https://localhost:6443</span></span></code></pre></div><p>改為</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server: https://kmaster:6443</span></span></code></pre></div><p>出於安全考慮，只對自己保留這個配置文件的讀寫權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod 600 ~/.kube/config</span></span></code></pre></div>`,29)),t("p",null,[s[15]||(s[15]=e("如果 PC 上還沒有安裝 ",-1)),s[16]||(s[16]=t("code",null,"kubectl",-1)),s[17]||(s[17]=e(" 的話，就可以開始安裝了。Kubernetes 官方網站上有各種平台安裝 ",-1)),s[18]||(s[18]=t("code",null,"kubectl",-1)),s[19]||(s[19]=e(" 的",-1)),a(i,{href:"https://kubernetes.io/docs/tasks/tools/install-kubectl/"},{default:n(()=>[...s[14]||(s[14]=[e("方法説明",-1)])]),_:1}),s[20]||(s[20]=e("，我使用的是 Ubuntu 的衍生版 Linux Mint，所以我的安裝方法是這樣的：",-1))]),s[46]||(s[46]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt install -y apt-transport-https</span></span>
<span class="line"><span>curl -s https://packages.cloud.google.com/apt/doc/apt-key.gpg | sudo apt-key add -</span></span>
<span class="line"><span>echo &quot;deb https://apt.kubernetes.io/ kubernetes-xenial main&quot; | sudo tee -a /etc/apt/sources.list.d/kubernetes.list</span></span>
<span class="line"><span>sudo apt update &amp;&amp; sudo apt install kubectl</span></span></code></pre></div><p>上面幾個命令的作用是添加了一個包含 Kubernetes 的 Debian 軟件庫，獲取 GPG 密鑰以確保安全，然後更新軟件包列表並安裝 <code>kubectl</code>。如果 <code>kubectl</code> 有更新，我們將會通過<ruby>標準軟件更新機制<rt>standard software update mechanism</rt></ruby>收到通知。</p><p>現在在 PC 上就可以查看 Kubernetes 集羣了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kubectl get nodes</span></span></code></pre></div><p>輸出大概會是這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME     STATUS  ROLES   AGE   VERSION</span></span>
<span class="line"><span>kmaster  Ready   master  12m   v1.14.3-k3s.1</span></span>
<span class="line"><span>knode1   Ready   worker  103s  v1.14.3-k3s.1</span></span>
<span class="line"><span>knode1   Ready   worker  103s  v1.14.3-k3s.1</span></span></code></pre></div><p>至此，我們已經搭建了一個三節點的 Kubernetes 集羣。</p><h3 id="k3s-的彩蛋" tabindex="-1">K3s 的彩蛋 <a class="header-anchor" href="#k3s-的彩蛋" aria-label="Permalink to “K3s 的彩蛋”">​</a></h3>`,8)),t("p",null,[s[22]||(s[22]=e("如果執行 ",-1)),s[23]||(s[23]=t("code",null,"kubectl get pods --all-namespaces",-1)),s[24]||(s[24]=e("，就會看到其它服務的一些 Pod，比如 ",-1)),a(i,{href:"https://traefik.io/"},{default:n(()=>[...s[21]||(s[21]=[e("Traefik",-1)])]),_:1}),s[25]||(s[25]=e("。Traefik 在這裏起到是反向代理和負載均衡器的作用，它可以讓流量從單個入口進入集羣后引導到集羣中的各個服務。Kubernetes 支持這種機制，但 Kubernetes 本身不提供這個功能，因此 Traefik 是一個不錯的選擇，K3s 安裝後立即可用的優點也得益於此。",-1))]),s[47]||(s[47]=t("p",null,"在後續的文章中，我們會繼續探討 Traefik 在 Kubernetes ingress 中的應用，以及在集羣中部署其它組件。敬請關注。",-1)),s[48]||(s[48]=t("hr",null,null,-1)),t("p",null,[s[27]||(s[27]=e("via: ",-1)),a(i,{href:"https://opensource.com/article/20/3/kubernetes-raspberry-pi-k3s"},{default:n(()=>[...s[26]||(s[26]=[e("https://opensource.com/article/20/3/kubernetes-raspberry-pi-k3s",-1)])]),_:1})]),t("p",null,[s[32]||(s[32]=e("作者：",-1)),a(i,{href:"https://opensource.com/users/carpie"},{default:n(()=>[...s[28]||(s[28]=[e("Lee Carpenter",-1)])]),_:1}),s[33]||(s[33]=e(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[29]||(s[29]=[e("lujun9972",-1)])]),_:1}),s[34]||(s[34]=e(" 譯者：",-1)),a(i,{href:"https://github.com/HankChow"},{default:n(()=>[...s[30]||(s[30]=[e("HankChow",-1)])]),_:1}),s[35]||(s[35]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[31]||(s[31]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[38]||(s[38]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[36]||(s[36]=[e("LCTT",-1)])]),_:1}),s[39]||(s[39]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[37]||(s[37]=[e("Linux中國",-1)])]),_:1}),s[40]||(s[40]=e(" 榮譽推出",-1))])])}const K=p(k,[["render",u]]);export{C as __pageData,K as default};
